while let Some(Ok(msg)) = stream.next().await {
    let (id, pos, size) = parse_seq(msg.headers());   // seq-id / pos / size
    let g = groups.entry(id).or_insert_with(|| vec![None; size]);
    g[pos - 1] = Some(msg.payload().unwrap().to_vec());
    if g.iter().all(Option::is_some) {
        deliver(std::mem::take(g));
        groups.remove(&id);
    }
}
